declare global {
  interface SanityQueries {
    '*[_type == "settings"][0]': SettingsQueryResult;
    '{\n  "home": *[_type == "home"][0],\n  "faqs": *[_type == "faq"] | order(order asc) { _id, question, answer }\n}': HomeQueryResult;
    '{\n  "page": *[_type == "featuresPage"][0],\n  "featureGrid": *[_type == "home"][0].featureGrid\n}': FeaturesQueryResult;
    '*[_type == "aboutPage"][0]': AboutQueryResult;
    '{\n  "plans": *[_type == "plan"] | order(order asc),\n  "faqs": *[_type == "faq"] | order(order asc) { _id, question, answer },\n  "faq": *[_type == "home"][0].faq\n}': PricingQueryResult;
    '{\n  "categories": *[_type == "category"] | order(order asc) { _id, title, "slug": slug.current },\n  "posts": *[_type == "post" && (!defined($category) || category->slug.current == $category)]\n    | order(isFeatured desc, publishedAt desc) { _id, title, "slug": slug.current, excerpt, author, readingMinutes, publishedAt,\n  "category": category->title, cover, isFeatured }\n}': BlogQueryResult;
    '{\n  "post": *[_type == "post" && slug.current == $slug][0] { _id, title, "slug": slug.current, excerpt, author, readingMinutes, publishedAt,\n  "category": category->title, cover, lede, body, tags },\n  "more": *[_type == "post" && slug.current != $slug] | order(publishedAt desc)[0...5] { _id, title, "slug": slug.current, excerpt, author, readingMinutes, publishedAt,\n  "category": category->title, cover }\n}': PostQueryResult;
    '*[_type == "post" && defined(slug.current)]{ "slug": slug.current }': PostSlugsQueryResult;
    '*[_type == "release"] | order(releasedAt desc)': ReleasesQueryResult;
    '*[_type == "legal" && slug.current == $slug][0]': LegalQueryResult;
    '*[_type == "legal" && defined(slug.current)]{ "slug": slug.current }': LegalSlugsQueryResult;
    '*[_type == "landing" && variant == $version][0]': LandingQueryResult;
    '{\n  "home": *[_type == "home"][0] { featureGrid, testimonials },\n  "faqs": *[_type == "faq"] | order(order asc)[0...3] { _id, question, answer }\n}': LandingExtrasQueryResult;
    '*[_type == "prelander"][0]': PrelanderQueryResult;
  }
}
